'use strict';
const LegacyUI=(()=>{
 let activeLife=null;
 const brief=(s,n=140)=>StoryPresentation.short(s,n);
 function photo(s){const entries=s.diary?.entries||[],candidates=entries.filter(e=>VisualMemory.has(e)&&!e.legacyEcologyMismatch&&!e.legacyAgeMismatch&&!e.visual.dead);return [...candidates].reverse().find(e=>e.visual.age>0&&Engine.ageEquivalent(e.visual.age,e.visual.race)>=18&&['decision','project','relationship','family'].includes(e.kind))||candidates[0]||null}
 function markup(s,{archiveView=false}={}){const r=LifeLegacy.summary(s),image=photo(s);return `<section class="legacy-card" aria-label="การ์ดบันทึกชีวิตของ ${esc(s.name)}"><div class="legacy-corners" aria-hidden="true"></div><div class="legacy-heading"><span>บันทึกแห่งชีวิต</span><small>NO. ${s.seed.toString(16).toUpperCase()}</small></div><figure class="legacy-scene"><canvas width="480" height="180" data-legacy-scene role="img" aria-label="ฉากความทรงจำในชีวิตนี้"></canvas><figcaption>${image?'ภาพจากบันทึกเมื่ออายุ '+image.age+' ปี · '+esc(image.title):'บ้านสุดท้าย · '+esc(KINGDOMS[s.kingdom][0])}</figcaption></figure><div class="legacy-name"><small>${esc(RACES[s.race][0])}${s.humanOrigin?' · '+esc(HumanOrigins.culture(s.humanOrigin.ethnicityId).name):''}</small><h2>${esc(s.name)}</h2><p>${esc(r.title)}</p></div><p class="legacy-intro">${esc(r.description)}</p><div class="legacy-measures"><div><b>${s.age}</b><span>ปีที่ได้ใช้ชีวิต</span></div><div><b>${s.turn}</b><span>ครั้งที่ได้เลือก</span></div><div><b>${r.worlds.length}</b><span>อาณาจักรที่เคยอยู่</span></div></div>${r.milestones.length?`<section class="legacy-chapters"><h3>หน้าที่ทำให้ชีวิตนี้เป็นของคุณ</h3><ol>${r.milestones.map(e=>`<li><span>${e.age}<small>ปี</small></span><div><b>${esc(e.title)}</b><p>${esc(brief(e.choice?'คุณเลือก'+e.choice:e.summary,130))}</p></div></li>`).join('')}</ol></section>`:''}${r.people.length?`<section class="legacy-people"><h3>เรื่องของคุณยังอยู่กับพวกเขา</h3>${r.people.map(p=>`<article><b>${esc(p.name)}</b><p>${esc(brief(p.text,160))}</p></article>`).join('')}</section>`:r.departed.length?`<section class="legacy-people"><h3>คนที่เคยเดินทางมาด้วยกัน</h3>${r.departed.map(p=>`<article><b>${esc(p.name)}</b><p>${esc(brief(p.text,160))}</p></article>`).join('')}</section>`:''}<div class="legacy-last"><span aria-hidden="true">· ✦ ·</span><p>${esc(s.cause)}</p><small>${r.migrated?'เรียบเรียงจากบันทึกที่ยังเก็บไว้ · ':''}ชีวิตนี้ถูกเก็บในหอจดหมายเหตุของคุณแล้ว</small></div><div class="legacy-actions"><button class="primary" data-legacy-export>เก็บการ์ดชีวิตนี้เป็นภาพ ↓</button>${archiveView?'<button class="secondary" data-legacy-log>อ่านบันทึกเหตุการณ์ทั้งหมด →</button>':`<button class="secondary" id="share">แบ่งปันเรื่องของชีวิตนี้</button><button class="legacy-next" id="reborn">เมื่อพร้อมแล้ว · เริ่มชีวิตใหม่ →</button>`}</div><p class="legacy-export-status" role="status" aria-live="polite"></p></section>`}
 function paint(root,s){root.querySelectorAll('[data-legacy-scene]').forEach(canvas=>{const e=photo(s);if(e)Illustration.drawScene(canvas,VisualMemory.read(s,e),0);else Illustration.drawScene(canvas,{...s,sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom,sceneOnly:false},0)})}
 function wrap(ctx,value,x,y,width,font,lineHeight,maxLines=10){ctx.font=font;let line='',lines=[];const parts=typeof Intl.Segmenter==='function'?[...new Intl.Segmenter('th',{granularity:'word'}).segment(String(value))].map(x=>x.segment):Array.from(String(value));for(const part of parts){if(ctx.measureText(line+part).width>width&&line){lines.push(line);line=part}else line+=part}if(line)lines.push(line);if(lines.length>maxLines){lines=lines.slice(0,maxLines);lines[maxLines-1]=lines[maxLines-1].slice(0,-2)+'…'}for(const line of lines){ctx.fillText(line,x,y);y+=lineHeight}return y}
 async function cardImage(s){await document.fonts.ready;const r=LifeLegacy.summary(s),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1740;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#f3f0e5';c.fillRect(0,0,1080,1740);c.strokeStyle='#8c987e';c.lineWidth=3;c.strokeRect(34,34,1012,1672);c.lineWidth=1;c.strokeRect(44,44,992,1652);for(const [x,y]of [[32,32],[1026,32],[32,1686],[1026,1686]]){c.fillStyle='#8f805f';c.fillRect(x,y,22,4);c.fillRect(x,y,4,22)}c.fillStyle='#6e7b62';c.font='22px "IBM Plex Sans Thai", sans-serif';c.fillText('1 in 10 Billion · FANTASY',72,96);c.textAlign='right';c.fillText(s.seed.toString(16).toUpperCase(),1008,96);c.textAlign='left';const shot=document.createElement('canvas');shot.width=480;shot.height=180;const e=photo(s);Illustration.drawScene(shot,e?VisualMemory.read(s,e):{...s,sceneOverride:(s.race?Ecology.profile(s).scene:'garden')+'-realm-'+s.kingdom},0);c.drawImage(shot,72,128,936,351);c.fillStyle='#63705d';c.font='19px "IBM Plex Sans Thai", sans-serif';c.fillText(e?'อายุ '+e.age+' ปี · '+brief(e.title,55):'บันทึกสุดท้ายจาก '+KINGDOMS[s.kingdom][0],72,512);c.fillStyle='#334339';let y=wrap(c,s.name,72,588,936,'bold 43px "IBM Plex Sans Thai", sans-serif',60,2);c.fillStyle='#7d7a66';y=wrap(c,r.title+' · '+RACES[s.race][0],72,y+14,936,'25px "IBM Plex Sans Thai", sans-serif',38,2);c.fillStyle='#465a4a';c.font='bold 37px "IBM Plex Sans Thai", sans-serif';c.fillText(s.age+' ปี',72,y+70);c.fillText(s.turn+' การตัดสินใจ',345,y+70);c.fillText(r.worlds.length+' อาณาจักร',735,y+70);y+=116;c.strokeStyle='#c6cdbb';c.beginPath();c.moveTo(72,y);c.lineTo(1008,y);c.stroke();y+=45;c.fillStyle='#405341';y=wrap(c,'หน้าที่ทำให้ชีวิตนี้เป็นของคุณ',72,y,936,'bold 25px "IBM Plex Sans Thai", sans-serif',38,1);for(const m of r.milestones.slice(0,3)){c.fillStyle='#99845a';c.font='23px "IBM Plex Sans Thai", sans-serif';c.fillText(m.age+' ปี',72,y+28);c.fillStyle='#3d4d40';const end=wrap(c,m.title,185,y+28,810,'bold 24px "IBM Plex Sans Thai", sans-serif',34,2);c.fillStyle='#74806c';y=wrap(c,brief(m.choice?'คุณเลือก'+m.choice:m.summary,115),185,end+2,810,'21px "IBM Plex Sans Thai", sans-serif',31,2)+22}const person=r.people[0]||r.departed[0];if(person&&y<1350){c.fillStyle='#6f7e63';y=wrap(c,r.people.length?'เรื่องของคุณยังอยู่กับ '+person.name:'คนที่เคยร่วมทาง · '+person.name,72,y+12,936,'bold 23px "IBM Plex Sans Thai", sans-serif',34,2);c.fillStyle='#69765f';y=wrap(c,brief(person.text,150),72,y+6,936,'22px "IBM Plex Sans Thai", sans-serif',34,3)}c.fillStyle='#937652';c.textAlign='center';c.font='24px Georgia';c.fillText('· ✦ ·',540,1590);c.fillStyle='#6f7869';c.font='20px "IBM Plex Sans Thai", sans-serif';c.fillText(brief(s.cause,78),540,1630);c.font='17px "IBM Plex Sans Thai", sans-serif';c.fillText('หนึ่งชีวิตที่เลือกเอง · '+r.origin,540,1666);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Image unavailable');return blob}
 function bind(root=document,s=state){paint(root,s);root.querySelectorAll('[data-legacy-log]').forEach(b=>b.onclick=()=>modal(`<h2>บันทึกของ ${esc(s.name)}</h2>${s.log.map(l=>`<div class="log"><strong>อายุ ${l.age} ปี</strong>${esc(l.text)}</div>`).join('')}`));root.querySelectorAll('[data-legacy-export]').forEach(b=>b.onclick=async()=>{const status=root.querySelector('.legacy-export-status');b.disabled=true;if(status)status.textContent='กำลังเก็บภาพและเรื่องราวของชีวิตนี้…';try{const blob=await cardImage(s),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fantasy-life-'+s.seed+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);if(status)status.textContent='เก็บการ์ดชีวิตนี้แล้ว · ไฟล์ PNG'}catch(e){if(status)status.textContent='ยังเก็บภาพไม่ได้ ลองอีกครั้งได้ครับ'}finally{b.disabled=false}})}
 function open(s){activeLife=s;modal(markup(s,{archiveView:true}));bind($('#modalBody'),s)}
 return {markup,paint,bind,open,cardImage};
})();
